classdef OneStepQLearnerTest < OceanTest.BaseTestCase
    % ONESTEPQLEARNERTEST  OceanAgents.Learners.OneStepQLearner (A0 sections 6.5 and 9.2). Gate IG06: the learner's
    % table equals an independent plain-arithmetic re-implementation (Fixtures.Learning.referenceQLearning) on a
    % long transition list generated by the real CliffWalking environment.

    methods (Static, Access = private)
        function t = transition(s, a, r, s2, varargin)
            % Transition over labels 1:4 (CliffWalking) with Discount 1 unless given.
            opts = struct('Terminated', false, 'Truncated', false, 'NextMask', true(1, 4), 'Discount', 1, ...
                'Labels', 1:4);
            for k = 1:2:numel(varargin), opts.(varargin{k}) = varargin{k + 1}; end
            t = OceanAgents.Core.Transition('AgentID', "agent1", 'EpisodeID', 1, 'Observation', s, 'Action', a, ...
                'ActionLabels', opts.Labels, 'Reward', r, 'NextObservation', s2, 'NextActionLabels', opts.Labels, ...
                'NextMask', opts.NextMask, 'Terminated', opts.Terminated, 'Truncated', opts.Truncated, ...
                'Discount', opts.Discount);
        end
        function t = envTransition(env, s, a, gamma)
            % One real CliffWalking step from state s, as the runtime would record it (Duration 1).
            env.set_state(s);
            [s2, r, term, trunc, info] = env.step(a);
            t = OceanAgents.Core.Transition('AgentID', "agent1", 'EpisodeID', 1, 'Observation', s, 'Action', a, ...
                'ActionLabels', 1:4, 'Reward', r, 'NextObservation', s2, 'NextActionLabels', 1:4, ...
                'NextMask', info.action_mask, 'Terminated', term, 'Truncated', trunc, 'Discount', gamma);
        end
        function [lrn, q] = cliffLearner(alpha, gamma)
            q = OceanStats.RL.TD.Values.TabularQ(true(48, 4));
            lrn = OceanAgents.Learners.OneStepQLearner(q, 1:4, 'Alpha', alpha, 'Gamma', gamma, ...
                'StateCodec', OceanAgents.Artifacts.DiscreteStateCodec(48));
        end
    end

    methods (Test)
        function cliffWalkingHandTable(tc)
            % A0 9.2, row by row, with the transitions produced by the real environment.
            env = OceanStats.RL.Env.Classic.CliffWalkingEnv();
            [lrn, q] = tc.cliffLearner(0.5, 1);
            %       s   a    r     s'  term  Q(s,a) after
            rows = [37  2  -100   37   0    -50
                    37  1    -1   25   0    -0.5
                    25  3    -1   37   0    -0.5
                    36  3    -1   48   1    -0.5];
            for k = 1:size(rows, 1)
                t = tc.envTransition(env, rows(k, 1), rows(k, 2), 1);
                tc.verifyEqual([t.Reward t.NextObservation double(t.Terminated)], rows(k, 3:5), ...
                    sprintf('environment disagrees with A0 9.2 row %d', k));
                lrn.consume(t);
                tc.verifyEqual(lrn.update("step"), 1);
                tc.verifyEqual(q.Q(rows(k, 1), rows(k, 2)), rows(k, 6), sprintf('A0 9.2 row %d', k));
                if k == 3
                    tc.verifyEqual(q.Q(37, :), [-0.5 -50 0 0]);
                    tc.verifyEqual(q.Q(25, :), [0 0 -0.5 0]);
                end
            end
            tc.verifyEqual(nnz(q.Q), 4);
            tc.verifyEqual(sum(q.Counts(:)), 4);
            tc.verifyEqual(lrn.NumUpdates, 4);
        end

        function consumeWithoutUpdateChangesNothing(tc)
            [lrn, q] = tc.cliffLearner(0.5, 1);
            lrn.consume(tc.transition(37, 2, -100, 37));
            tc.verifyEqual(q.Q, zeros(48, 4));
            tc.verifyEqual(q.Counts, zeros(48, 4));
            tc.verifyEqual(lrn.numPending(), 1);
            tc.verifyEqual(lrn.update("episode"), 0);         % boundary "step": nothing due at "episode"
            tc.verifyEqual(q.Q, zeros(48, 4));
            tc.verifyEqual(lrn.numPending(), 1);
            tc.verifyEqual(lrn.update("step"), 1);
            tc.verifyEqual(q.Q(37, 2), -50);
            tc.verifyEqual(lrn.numPending(), 0);
            tc.verifyEqual(lrn.update("step"), 0);
            tc.verifyError(@() lrn.update("frame"), 'MATLAB:validators:mustBeMember');
        end

        function truncationWithoutSuccessorMaskIsRefused(tc)
            [lrn, q] = tc.cliffLearner(0.5, 1);
            t = tc.transition(13, 3, -1, 25, 'Truncated', true, 'NextMask', false(1, 4));
            tc.verifyError(@() lrn.consume(t), 'OceanAgents:Learners:MissingSuccessorMask');
            tc.verifyEqual(lrn.numPending(), 0);
            tc.verifyEqual(q.Q, zeros(48, 4));
        end

        function truncationWithSuccessorMaskBootstraps(tc)
            % Q(25,:) = [2 -1 -1 -1]. Truncated transition 13 --3--> 25, r = -1, alpha = 0.5, gamma = 1:
            %   all successor actions legal: y = -1 + 2 = 1            -> Q(13,3) = 0.5   (a terminal would give -0.5)
            %   successor mask [F T T T]:   y = -1 + max(-1,-1,-1) = -2 -> Q(13,3) = -1  (illegal a' excluded)
            [lrn, q] = tc.cliffLearner(0.5, 1);
            q.applyIncrement(full(sparse(25, 1:4, [2 -1 -1 -1], 48, 4)));
            lrn.consume(tc.transition(13, 3, -1, 25, 'Truncated', true, 'NextMask', true(1, 4)));
            lrn.update("step");
            tc.verifyEqual(q.Q(13, 3), 0.5);

            [lrn, q] = tc.cliffLearner(0.5, 1);
            q.applyIncrement(full(sparse(25, 1:4, [2 -1 -1 -1], 48, 4)));
            lrn.consume(tc.transition(13, 3, -1, 25, 'Truncated', true, 'NextMask', [false true true true]));
            lrn.update("step");
            tc.verifyEqual(q.Q(13, 3), -1);

            % the same exclusion for an ordinary (non-ended) transition
            [lrn, q] = tc.cliffLearner(0.5, 1);
            q.applyIncrement(full(sparse(25, 1:4, [2 -1 -1 -1], 48, 4)));
            lrn.consume(tc.transition(13, 3, -1, 25, 'NextMask', [false true true true]));
            lrn.update("step");
            tc.verifyEqual(q.Q(13, 3), -1);
        end

        function discountIsGammaToTheDuration(tc)
            % gamma = 0.9: target = r + 0.9 * max Q(s',:) with Q(25,:) = [2 ...]; alpha = 1 -> Q = -1 + 1.8.
            [lrn, q] = tc.cliffLearner(1, 0.9);
            q.applyIncrement(full(sparse(25, 1:4, [2 -1 -1 -1], 48, 4)));
            lrn.consume(tc.transition(13, 3, -1, 25, 'Discount', 0.9));
            lrn.update("step");
            tc.verifyEqual(q.Q(13, 3), -1 + 0.9 * 2, 'AbsTol', 1e-15);
            tc.verifyError(@() lrn.consume(tc.transition(13, 3, -1, 25, 'Discount', 1)), ...
                'OceanAgents:Learners:Incompatible');
        end

        function labelsMapThroughTheCodec(tc)
            % Labels 0..3 (Start 0): action label 1 is Q column 2; observations 0..47 are rows 1..48.
            q = OceanStats.RL.TD.Values.TabularQ(true(48, 4));
            lrn = OceanAgents.Learners.OneStepQLearner(q, 0:3, 'Alpha', 0.5, 'Gamma', 1, ...
                'StateCodec', OceanAgents.Artifacts.DiscreteStateCodec(48, 'Start', 0));
            lrn.consume(tc.transition(36, 1, -100, 36, 'Labels', 0:3));
            lrn.update("step");
            tc.verifyEqual(q.Q(37, 2), -50);
            tc.verifyEqual(nnz(q.Q), 1);
            tc.verifyError(@() lrn.consume(tc.transition(48, 1, -1, 36, 'Labels', 0:3)), ...
                'OceanAgents:Artifacts:UnknownState');
            tc.verifyError(@() lrn.consume(tc.transition(1, 1, -1, 2)), 'OceanAgents:Learners:Incompatible');
        end

        function checkCompatibleWithPolicies(tc)
            [lrn, q] = tc.cliffLearner(0.5, 1);
            eg = OceanAgents.Policies.EpsilonGreedyQPolicy(q, 1:4, 'Epsilon', 0.1);
            lrn.checkCompatible(eg.describe());
            lrn.checkCompatible(OceanAgents.Policies.RandomLegalPolicy().describe());   % label-agnostic behaviour
            other = OceanAgents.Policies.EpsilonGreedyQPolicy(q, 0:3);
            tc.verifyError(@() lrn.checkCompatible(other.describe()), 'OceanAgents:Learners:Incompatible');
            tc.verifyError(@() lrn.checkCompatible(struct('Name', "x", 'NumActions', 3)), 'OceanAgents:Learners:Incompatible');
            tc.verifyError(@() OceanAgents.Learners.OneStepQLearner(q, 1:3), 'OceanAgents:Learners:Incompatible');
            d = lrn.describe();
            tc.verifyEqual([d.Name d.Boundary], ["OneStepQLearner" "step"]);
            tc.verifyEqual(d.Gamma, 1);
        end

        function policyAndLearnerShareOneTable(tc)
            % Intended intra-agent sharing: the learner's update is what the policy acts on next.
            [lrn, q] = tc.cliffLearner(0.5, 1);
            pol = OceanAgents.Policies.EpsilonGreedyQPolicy(q, 1:4, 'Epsilon', 0);
            v = OceanAgents.Core.ActorView('AgentID', "agent1", 'EpisodeID', 1, 'FrameID', 1, ...
                'Observation', 37, 'ActionLabels', 1:4, 'ActionMask', true(1, 4));
            tc.verifyEqual(pol.probabilities(v), [1 1 1 1] / 4);
            lrn.consume(tc.transition(37, 2, -100, 37));
            lrn.update("step");
            tc.verifyEqual(pol.probabilities(v), [1 0 1 1] / 3, 'AbsTol', 1e-15);
            tc.verifySameHandle(lrn.Q, pol.Q);
        end

        function exportImportRoundTripDoesNotAlias(tc)
            env = OceanStats.RL.Env.Classic.CliffWalkingEnv();
            [lrn, q] = tc.cliffLearner(0.3, 0.9);
            steps = tc.randomWalk(env, 600, 0.9, 11);
            for k = 1:numel(steps)
                lrn.consume(steps{k});
                lrn.update("step");
            end
            s = lrn.exportState();
            [fresh, q2] = tc.cliffLearner(0.3, 0.9);
            pol2 = OceanAgents.Policies.EpsilonGreedyQPolicy(q2, 1:4);
            fresh.importState(s);
            tc.verifyEqual(q2.Q, q.Q);                         % bit-for-bit
            tc.verifyEqual(q2.Counts, q.Counts);
            tc.verifyEqual(fresh.NumUpdates, lrn.NumUpdates);
            tc.verifySameHandle(pol2.Q, q2, 'the fresh agent keeps its own policy/learner sharing');
            tc.verifyNotSameHandle(q2, q);
            % later learning in the original agent reaches neither the export nor the imported agent
            snapshot = q2.Q;
            lrn.consume(tc.transition(37, 2, -100, 37, 'Discount', 0.9));
            lrn.update("step");
            tc.verifyEqual(q2.Q, snapshot);
            tc.verifyEqual(s.Q, snapshot);
            tc.verifyNotEqual(q.Q, snapshot);
            % importing into an agent that has already learned overwrites its tables exactly (checkpoint restore)
            lrn.importState(s);
            tc.verifyEqual(q.Q, s.Q);
            tc.verifyEqual(q.Counts, s.Counts);
        end

        function importRejectsBadStates(tc)
            [lrn, ~] = tc.cliffLearner(0.5, 1);
            s = lrn.exportState();
            bad = s;  bad.Counts(1, 1) = -1;
            tc.verifyError(@() lrn.importState(bad), 'OceanAgents:Learners:Incompatible');   % negative count
            bad = s;  bad.Q(2, 2) = NaN;
            tc.verifyError(@() lrn.importState(bad), 'OceanAgents:Learners:Incompatible');   % non-finite Q
            [third, ~] = tc.cliffLearner(0.4, 1);
            tc.verifyError(@() third.importState(s), 'OceanAgents:Learners:Incompatible');   % Alpha differs
            bad = s;  bad.Q = zeros(47, 4);
            tc.verifyError(@() lrn.importState(bad), 'OceanAgents:Learners:Incompatible');
            tc.verifyError(@() lrn.importState(struct('Name', "x")), 'OceanAgents:Learners:Incompatible');
        end

        function importValidatesPendingEntries(tc)
            % N4: a pending entry is checked at import, not left to fail later inside update().
            [src, ~] = tc.cliffLearner(0.5, 1);
            src.consume(tc.transition(37, 2, -100, 37));          % one genuine pending entry
            s = src.exportState();
            [ok, q] = tc.cliffLearner(0.5, 1);
            ok.importState(s);                                    % the genuine entry is accepted ...
            tc.verifyEqual(ok.numPending(), 1);
            tc.verifyEqual(ok.update("step"), 1);                 % ... and applies like the original
            tc.verifyEqual(q.Q(37, 2), -50);
            corrupt = { ...
                @(p) setfield(p, 'si', 49), ...                   % row outside 1..48
                @(p) setfield(p, 's2i', 0), ...
                @(p) setfield(p, 'ai', 5), ...                    % column outside 1..4
                @(p) setfield(p, 'ai', 1.5), ...
                @(p) setfield(p, 'r', NaN), ...
                @(p) setfield(p, 'term', 1), ...                  % not logical
                @(p) setfield(p, 'discount', 1.5), ...
                @(p) setfield(p, 'valid2', [1 1 1 1]), ...        % not logical
                @(p) setfield(p, 'valid2', true(1, 3)), ...       % wrong width
                @(p) setfield(p, 'valid2', false(1, 4))};         % non-terminal without successor legality
            for k = 1:numel(corrupt)
                bad = s;  bad.Pending = corrupt{k}(s.Pending);
                [fresh, q2] = tc.cliffLearner(0.5, 1);
                tc.verifyError(@() fresh.importState(bad), 'OceanAgents:Learners:Incompatible', sprintf('corruption %d', k));
                tc.verifyEqual(fresh.numPending(), 0, 'a refused import changes nothing');
                tc.verifyEqual(q2.Q, zeros(48, 4));
            end
            bad = s;  bad.NumUpdates = -1;
            tc.verifyError(@() ok.importState(bad), 'OceanAgents:Learners:Incompatible');
        end

        function matchesIndependentReimplementation(tc)
            % IG06: 5000 real CliffWalking transitions (random legal actions, random resets, every 40th step
            % recorded as a time-limit truncation carrying its successor mask), gamma = 0.9, alpha = 0.3.
            env = OceanStats.RL.Env.Classic.CliffWalkingEnv();
            gamma = 0.9;  alpha = 0.3;
            [lrn, q] = tc.cliffLearner(alpha, gamma);
            steps = tc.randomWalk(env, 5000, gamma, 20260928);
            plain = struct('s', {}, 'a', {}, 'r', {}, 's2', {}, 'term', {}, 'discount', {}, 'valid2', {});
            nTrunc = 0;  nTerm = 0;
            for k = 1:numel(steps)
                t = steps{k};
                lrn.consume(t);
                tc.assertEqual(lrn.update("step"), 1);
                plain(end + 1) = struct('s', t.Observation, 'a', t.Action, 'r', t.Reward, ...
                    's2', t.NextObservation, 'term', t.Terminated, 'discount', t.Discount, 'valid2', t.NextMask); %#ok<AGROW>
                nTrunc = nTrunc + t.Truncated;  nTerm = nTerm + t.Terminated;
            end
            [Qref, Nref] = OceanTest.OceanAgents.Fixtures.Learning.referenceQLearning(zeros(48, 4), plain, alpha);
            tc.verifyEqual(q.Q, Qref, 'AbsTol', 1e-12);
            tc.verifyEqual(q.Counts, Nref);
            tc.assertGreaterThan(nTrunc, 10, 'the list must exercise truncation');
            tc.assertGreaterThan(nTerm, 0, 'the list must exercise termination');
            tc.assertGreaterThan(nnz(q.Q), 40, 'the list must touch many entries');
        end

        function pillars(tc)
            [lrn, ~] = tc.cliffLearner(0.5, 1);
            m = OceanAgents.Learners.OneStepQLearner.getMetadata();
            tc.verifyTrue(m.IsSymbolic);
            tc.verifyEqual(m.SymbolicLatex, ...
                "Q(s,a) \leftarrow Q(s,a) + \alpha\,[r + \gamma^{k}(1-d)\max_{a'\in\mathcal{L}(s')}Q(s',a') - Q(s,a)]");
            tc.verifySubstring(m.Reference, "eq. 6.8");
            tc.verifyTrue(all(isfield(m, {'id', 'display_name', 'textbook', 'pedagogy', 'equations', 'Symbols', ...
                'parameters', 'complexity', 'strengths', 'weaknesses', 'when_to_use', 'references', 'Assumptions'})));
            tc.verifyEqual(lrn.getMetadata().SymbolicLatex, m.SymbolicLatex);
            s = lrn.getPipelineSpec();
            tc.verifyEqual(s.Inputs.Domain, "Agent-Transition");
        end
    end

    methods (Static, Access = private)
        function steps = randomWalk(env, n, gamma, seed)
            % n real transitions: uniformly random legal actions from a seeded stream; an episode restarts at a
            % random non-terminal state after termination and after every 40-step truncation.
            rs = RandStream('mrg32k3a', 'Seed', seed);
            env.reset('Seed', seed);
            starts = find(any(env.ValidMask, 2));
            s = starts(randi(rs, numel(starts)));
            steps = cell(1, n);
            len = 0;
            for k = 1:n
                env.set_state(s);
                legal = find(env.ValidMask(s, :));
                a = legal(randi(rs, numel(legal)));
                [s2, r, term, ~, info] = env.step(a);
                len = len + 1;
                trunc = ~term && len == 40;
                steps{k} = OceanAgents.Core.Transition('AgentID', "agent1", 'EpisodeID', 1, 'Observation', s, ...
                    'Action', a, 'ActionLabels', 1:4, 'Reward', r, 'NextObservation', s2, 'NextActionLabels', 1:4, ...
                    'NextMask', info.action_mask, 'Terminated', term, 'Truncated', trunc, 'Discount', gamma);
                if term || trunc
                    s = starts(randi(rs, numel(starts)));
                    len = 0;
                else
                    s = s2;
                end
            end
        end
    end
end
